import pandas as pd, numpy as np, statsmodels.formula.api as smf
df = pd.read_csv('data.csv')
controls = 'log_hist_days + log_pre_gmv + orders + cat_share + tenure + C(region) + C(tier)'
# Compare bs df=4,5,6 and cr df=4,5,6 using AIC/BIC maybe
for spline in ['bs(D, df=4, degree=3, include_intercept=False)','bs(D, df=5, degree=3, include_intercept=False)','bs(D, df=6, degree=3, include_intercept=False)','cr(D, df=4)','cr(D, df=5)','cr(D, df=6)']:
    try:
        res = smf.ols(f'dY ~ {spline} + {controls}', data=df).fit()
        print(f'{spline}: R2={res.rsquared:.4f}, AIC={res.aic:.1f}, BIC={res.bic:.1f}')
    except Exception as e:
        print(spline, 'error', e)
